function plusOne(head) {
  const sentinel = new ListNode(0, head);
  let lastNotNine = sentinel;
  let node = head;

  while (node !== null) {
    if (node.val !== 9) {
      lastNotNine = node;
    }
    node = node.next;
  }

  lastNotNine.val += 1;
  node = lastNotNine.next;
  while (node !== null) {
    node.val = 0;
    node = node.next;
  }

  return sentinel.val === 1 ? sentinel : sentinel.next;
}

