function plusOne(head) {
  // Copy the digits into an array, add one with a carry from the right, and rebuild the list.
  const digits = [];
  for (let p = head; p; p = p.next) digits.push(p.val);
  let carry = 1;
  for (let i = digits.length - 1; i >= 0 && carry; i--) {
    const total = digits[i] + carry;
    digits[i] = total % 10;
    carry = Math.floor(total / 10);
  }
  if (carry) digits.unshift(carry);
  let result = null;
  for (let k = digits.length - 1; k >= 0; k--) result = new ListNode(digits[k], result);
  return result;
}

