function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 7);
  // Many trailing nines make the carry travel; sometimes every digit is a nine.
  const nineRate = rand() < 0.25 ? 1 : rand() * 0.8;
  const digits = Array.from({ length: n }, () => (rand() < nineRate ? 9 : Math.floor(rand() * 10)));
  if (n > 1 && digits[0] === 0) digits[0] = 1 + Math.floor(rand() * 9);
  return [digits];
}
